Q: How to convert an int to a binary string  representation in C++ A: <p>Without using bitset and &lt;cmath&gt;</p>
<pre><code>#include &lt;iostream&gt;
using namespace std;

int main() {
    int n;
    cout &lt;&lt; &quot;Enter a number: &quot;;
    cin &gt;&gt; n;

    long long bin = 0;
    int place = 1;          // represents 1, 10, 100, 1000...

    while (n &gt; 0) {
        bin += (n &amp; 1) * place;  // attach bit at correct decimal place
        n &gt;&gt;= 1;
        place *= 10;
    }

    cout &lt;&lt; bin;
    return 0;
}
</code></pre>
